        guru::TOPIC_ATTRACTORS,
        guru::TOPIC_STRESSORS,
        guru::TOPIC_PURPOSES,
        guru::TOPIC_PERSONAS,
        guru::TOPIC_WHOLE_SYSTEM_RESIDUE,
        guru::TOPIC_WALK_REMINDER,
    )
}

/// Classify a discussion snippet against `skills::guru` topics and, subject to
