119	pub fn check(name: &str, agent: &str) -> Result<()> {
120	    let _ = find(name).with_context(|| format!("skill '{}' not found", name))?;
121	    let agent_parsed: install::Agent = agent.parse()?;
122	    let path = install::install_path(name, &agent_parsed, false)?;
123	    if !path.exists() {
124	        println!("'{}' is not installed for agent '{}'.", name, agent);
125	        return Ok(());
126	    }
127	    let content = std::fs::read_to_string(&path)
128	        .with_context(|| format!("failed to read {}", path.display()))?;
129	    if install::is_passthrough_stub(&content) {
130	        println!(
131	            "'{}' is a passthrough stub — methodology lives in the binary (`residual skill show {}`).",
132	            name, name
133	        );
134	        return Ok(());
135	    }
136	    // Legacy versioned install: compare front-matter version to embedded.
137	    let embedded_version = find(name).map(|(_, v)| v).unwrap_or(0);
138	    match install::parse_version_from_front_matter(&content) {
139	        Some(installed_ver) if installed_ver == embedded_version => {
140	            println!("'{}' is up to date (version {}).", name, installed_ver);
141	        }
142	        Some(installed_ver) => {
143	            println!(
144	                "'{}' is outdated: installed version {}, embedded version {}. Re-run `residual skill install {}` for a passthrough stub.",
145	                name, installed_ver, embedded_version, name
146	            );
147	        }
148	        None => {
149	            println!(
150	                "'{}' is a legacy install without passthrough or version — re-run `residual skill install {}`.",
151	                name, name
152	            );
153	        }
154	    }
155	    Ok(())
156	}
